'use strict';
const $=s=>document.querySelector(s), classes=['Playgroup','Nursery','Jr. Kg','Sr. Kg'], KEY='little-ledger-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10), uid=()=>crypto.randomUUID(), money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:data.currency}).format(n||0);
const initial=()=>({schema:1,revision:uid(),datasetId:uid(),activities:[],deletedRecords:[],school:'My Preschool',currency:'INR',years:{'2026–2027':{fees:Object.fromEntries(classes.map(c=>[c,0]))}},students:[],payments:[]});
let data, year,tab='summary',search='',classFilter='',statusFilter='',editing=null,folder=null,folderRevision=null,busy=false,cloudRevision=null,cloudLoaded=false,saveChain=Promise.resolve(),activityTimer=null,historySearch='',historyYear='';
try{data=JSON.parse(localStorage.getItem(KEY))||initial();validate(data)}catch(e){data=initial();validate(data);alert('Saved browser data could not be read. Restore a JSON backup from Settings before entering records.');}
year=Object.keys(data.years).sort().at(-1);
function validate(d){Admin.normalize(d);Performance.normalize(d);Admissions.normalize(d);if(d){d.datasetId=d.datasetId||d.revision;d.activities=d.activities??[];d.deletedRecords=d.deletedRecords??[];if(!Array.isArray(d.activities)||!Array.isArray(d.deletedRecords))throw Error('Invalid history or deleted records');for(const e of d.activities)if(!e||typeof e.id!=='string'||typeof e.at!=='string'||!Number.isFinite(Date.parse(e.at))||['action','actor','subject','details','year','outcome'].some(k=>typeof e[k]!=='string'))throw Error('Invalid activity history');for(const x of d.deletedRecords)if(!x||!/^[0-9a-f-]{36}$/i.test(x.id)||!Number.isFinite(Date.parse(x.deletedAt))||!['student','payment','year','branch'].includes(x.kind)||(x.kind==='student'&&(!x.student||!Array.isArray(x.payments)))||(x.kind==='payment'&&!x.payment)||(x.kind==='year'&&(!x.year||!x.fees)))throw Error('Invalid deleted record');}if(!d||d.schema!==1||!d.years||!Object.keys(d.years).length||!Array.isArray(d.students)||!Array.isArray(d.payments)||!d.revision)throw Error('Not a valid Little wings preschool ledger backup'); new Intl.NumberFormat(undefined,{style:'currency',currency:d.currency});for(const y of Object.values(d.years))for(const c of classes)if(!Number.isFinite(y.fees?.[c])||y.fees[c]<0)throw Error('Invalid annual fees');const ids=new Set();for(const s of d.students){if(!/^[0-9a-f-]{36}$/i.test(s.id)||ids.has(s.id)||!d.years[s.year]||!classes.includes(s.class)||!Number.isFinite(s.discount)||s.discount<0)throw Error('Invalid student record');ids.add(s.id)}const paymentIds=new Set();for(const p of d.payments){if(paymentIds.has(p.id)||!/^[0-9a-f-]{36}$/i.test(p.id)||typeof p.date!=='string'||!ids.has(p.student)||!Number.isFinite(p.amount)||p.amount<=0)throw Error('Invalid payment record');paymentIds.add(p.id)}Admin.validate(d);Performance.validate(d);Admissions.validate(d)}
function notice(t){$('#notice').textContent=t;$('#notice').scrollIntoView?.({block:'nearest',behavior:'smooth'})}
function rows(){return data.students.filter(s=>s.year===year&&s.branchId===branchId)}
function paid(s){return cents(data.payments.filter(p=>p.student===s.id).reduce((a,p)=>a+p.amount,0))}
function cents(n){return Math.round((n+Number.EPSILON)*100)/100}
function net(s){return cents(Math.max(0,Admin.fees(data,s)[s.class]-s.discount))}
function balance(s){return cents(net(s)-paid(s))}
function name(s){return [s.first,s.middle,s.surname].filter(Boolean).join(' ')}
function selected(){return rows().filter(s=>(!classFilter||s.class===classFilter)&&(!statusFilter||(statusFilter==='due'?balance(s)>0:balance(s)<=0))&&[name(s),s.father,s.mother,s.mobile,s.admission].join(' ').toLowerCase().includes(search.toLowerCase()))}
async function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('little-ledger-folder',1);r.onupgradeneeded=()=>r.result.createObjectStore('settings');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function handleStore(value){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('settings',value===undefined?'readonly':'readwrite'),store=tx.objectStore('settings');const r=value===undefined?store.get('folder'):store.put(value,'folder');tx.oncomplete=()=>{resolve(r.result);d.close()};tx.onerror=()=>reject(tx.error)})}
async function readFolder(){try{const h=await folder.getFileHandle('preschool-records.json');const file=await h.getFile();const d=JSON.parse(await file.text());validate(d);return d}catch(e){if(e.name==='NotFoundError')return null;throw e}}
async function permission(){if(!folder)return false;if(await folder.queryPermission({mode:'readwrite'})==='granted')return true;return await folder.requestPermission({mode:'readwrite'})==='granted'}
function recordContent(d){return JSON.stringify([d.school,d.currency,d.years,d.students,d.payments,d.deletedRecords,d.branches,d.staff,d.staffEntries,d.attendance,d.salarySnapshots,d.subjectMasters,d.performance,d.admissionSequences]);}
function activity(action,subject='',details='',eventYear=year,outcome='Success'){History.queue(History.event(data.datasetId,action,subject,details,eventYear,outcome));scheduleActivitySync();}
function scheduleActivitySync(){if(activityTimer)return;activityTimer=setTimeout(async()=>{activityTimer=null;if(busy){scheduleActivitySync();return}await syncActivities();},1500);}
async function syncActivities(){if(!History.pending(data.datasetId).length)return true;if(OneDrive.enabled()&&!cloudLoaded)return false;return commit(clone(),{logOnly:true,quiet:true});}
function commit(next,options={}){
 const base=recordContent(data);
 const operation=async()=>{busy=true;try{
  if(recordContent(data)!==base)throw Error('Records changed while this save was waiting. Review the latest records and try again.');
  validate(next);if(!options.reset)for(const [key,value] of Object.entries(data.admissionSequences))next.admissionSequences[key]=Math.max(value,next.admissionSequences[key]||0);next.datasetId=options.reset?uid():data.datasetId;
  const pending=History.pending(data.datasetId),changes=options.logOnly||options.reset?[]:[...History.changes(data,next),...Admin.changes(data,next),...Performance.changes(data,next)];if(options.event)changes.push(History.event(data.datasetId,options.event.action,options.event.subject||'',options.event.details||'',options.event.year||''));
  next.activities=options.reset?[]:History.merge(data.activities,next.activities,pending,changes);
  if(OneDrive.enabled()){if(!cloudLoaded)throw Error('Load your OneDrive records in Settings before editing.');next.revision=uid();await OneDrive.write(next,cloudRevision);cloudRevision=next.revision;}
  else if(folder){if(!await permission())throw Error('Folder permission is needed. Reconnect the folder in Settings.');const disk=await readFolder();if((disk?.revision??null)!==folderRevision)throw Error('The folder data changed. Your edit was not saved. Reload folder data in Settings.');next.revision=uid();const h=await folder.getFileHandle('preschool-records.json',{create:true}),stream=await h.createWritable();try{await stream.write(JSON.stringify(next,null,2));await stream.close()}catch(e){await stream.abort().catch(()=>{});throw e}folderRevision=next.revision;}
  else next.revision=uid();
  try{localStorage.setItem(KEY,JSON.stringify(next))}catch(e){if(!OneDrive.enabled()&&!folder)throw Error('Browser storage is full. Download a JSON backup and connect a folder before saving more records.');if(!options.quiet)notice('Saved to your storage; the browser cache is full.');}
  if(options.reset)History.synced(History.pending().map(e=>e.id));data=next;if(!data.years[year])year=Object.keys(data.years).sort().at(-1);History.synced(pending.map(e=>e.id));
  if(!options.quiet){notice(OneDrive.enabled()?'Saved to OneDrive, including activity history.':folder?'Saved to the folder, including activity history.':'Saved in this browser, including activity history.');render();}else if(tab==='history')render();
  return true;
 }catch(e){if(!options.logOnly)activity('Save failed','Records','No record changes were saved.',year,'Failed');if(!options.quiet)notice(e.message);return false;}finally{busy=false;}};
 const result=saveChain.then(operation);saveChain=result.then(()=>{},()=>{});return result;
}
function clone(){return structuredClone(data)}
