if(tab==='fees'||tab==='reports'){html=heading(tab==='fees'?'Fees & payments':'Reports',tab==='fees'?'Annual fees, individual discounts and receipt history.':'Filter records and download the selected year as an Excel workbook.')+filters()+`<div class="toolbar"><button class="primary" data-action="payment">Record payment</button><button data-action="exportFiltered">Export filtered Excel</button><button data-action="exportAll">Export branch · all years</button></div><div class="panel">${table(['Student','Class','Annual fee','Discount','Net fee','Collected','Due / credit',''],filtered.map(s=>`<tr><td>${esc(name(s))}</td><td>${s.class}</td><td>${money(Admin.fees(data,s)[s.class])}</td><td>${money(s.discount)}</td><td>${money(net(s))}</td><td>${money(paid(s))}</td><td><span class="badge ${balance(s)>0?'due':'paid'}">${balance(s)<0?money(-balance(s))+' credit':money(balance(s))}</span></td><td><button data-edit="${s.id}">Edit discount</button><button data-pay="${s.id}">Payment</button></td></tr>`).join(''))}</div><div class="panel"><h2>Payment history</h2>${table(['Date','Student','Amount','Method','Receipt / reference','Notes',''],data.payments.filter(p=>filtered.some(s=>s.id===p.student)).sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${esc(p.date)}</td><td>${esc(name(data.students.find(s=>s.id===p.student)))}</td><td>${money(p.amount)}</td><td>${esc(p.method)}</td><td>${esc(p.reference)}</td><td>${esc(p.notes)}</td><td><button class="danger" data-delete-payment="${p.id}">Delete payment</button></td></tr>`).join(''))}</div>`}
if(tab==='branches')html=renderBranches();if(tab==='staff'||tab==='staffmaster'){if(tab==='staffmaster')adminSection='master';else if(adminSection==='master')adminSection='salary';html=renderStaff();}if(tab==='subjects')html=renderSubjects();if(tab==='performance')html=renderPerformance();if(tab==='attendance')html=renderAttendance();if(tab==='history')html=renderHistory();
if(tab==='settings')html=heading('Year & storage settings','Configure annual fees and choose where your records are saved.')+`<div class="panel"><h2>School & academic years</h2><form id="operatorForm" class="inline"><label>Your name for activity history<input name="operator" maxlength="100" value="${esc(localStorage.getItem('ledger-operator-name')||'')}" placeholder="e.g. Teacher name"></label><button>Save name</button></form><form id="settingsForm"><div class="grid"><label>School name<input name="school" required value="${esc(data.school)}"></label><label>Currency<select name="currency">${['INR','USD','GBP','EUR','AED'].map(c=>`<option ${c===data.currency?'selected':''}>${c}</option>`).join('')}</select></label></div><h2>Annual fees · ${esc(currentBranch().name)} · ${esc(year)}</h2><div class="grid">${classes.map(c=>`<label>${c}<input name="${c}" type="number" min="0" step="0.01" required value="${(currentBranch().fees[year]||data.years[year].fees)[c]}"></label>`).join('')}</div><p class="setting-note">Changing these fees recalculates balances for this branch and year. Discounts remain fixed amounts.</p><button class="primary">Save settings</button></form><hr>${OneDrive.enabled()&&!cloudLoaded?'<p class="setting-note">OneDrive records have not been loaded. Connect OneDrive below, or choose browser storage to continue setup.</p><button type="button" id="setupBrowserMode">Use browser storage for now</button>':''}<form id="newYearForm"><div class="grid"><label>Start year<input name="startYear" type="number" inputmode="numeric" min="2000" max="2198" step="1" required value="${Number(year.slice(0,4))+1}"></label><label>End year<input name="endYear" type="number" inputmode="numeric" min="2001" max="2199" step="1" required value="${Number(year.slice(0,4))+2}"></label></div><button class="primary">Add academic year</button></form><button type="button" class="danger" id="deleteAcademicYear">Delete this academic year (only if empty)</button></div><div class="panel"><h2>OneDrive cloud · Android & Windows</h2><p class="setting-note">Save your Microsoft app ID and folder path, then sign in. Saving these settings alone does not switch your records to cloud storage. Both devices use the same cloud records. An internet connection is required for cloud saves. Your folder is remembered on each device; Microsoft may occasionally ask you to sign in again.</p><form id="cloudSettings"><div class="grid"><label>Microsoft Application (client) ID<input name="clientId" required value="${esc(OneDrive.config.clientId)}" placeholder="From Microsoft Entra app registration"></label><label>Account / tenant<select name="tenant">${['common','consumers','organizations'].map(t=>`<option ${OneDrive.config.tenant===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="full">OneDrive folder path<input name="path" required value="${esc(OneDrive.config.path)}" placeholder="School/Admissions"></label></div><p class="setting-note">Register this exact redirect URL as a Single-page application (SPA): <strong>${esc(OneDrive.redirect())}</strong>. See <a href="README.md" target="_blank" rel="noopener">setup instructions</a>. No client secret is needed.</p><button class="primary">Save OneDrive settings</button></form><p>${OneDrive.enabled()?(cloudLoaded?'Cloud records loaded.':OneDrive.signedIn()?'Signed in. Connect / load the folder.':'Cloud records not loaded. Sign in, or use browser storage while setting up.'):(OneDrive.config.clientId?'OneDrive settings saved. Browser storage stays active until the connection succeeds.':'Cloud storage not configured.')}</p><div class="inline"><button id="cloudLogin">Sign in with Microsoft</button><button type="button" id="cloudBrowse">Browse OneDrive folders</button><button id="cloudConnect">Connect folder / reload cloud data</button><button id="cloudDisconnect">Use browser storage instead</button><button id="exportConnection">Download connection settings</button><label>Import connection settings<input id="importConnection" type="file" accept=".json"></label></div><p class="setting-note">For collaborators: GitHub access does not grant OneDrive access. Share the school’s OneDrive folder with their Microsoft account using Can edit, and let them open that shared folder link here. Microsoft app registration must support their account type. Use one editor at a time. Reload cloud data before editing on a second device. Offline cloud edits are blocked to prevent conflicting records.</p></div><div class="panel"><h2>Local OneDrive folder · Windows only</h2><p class="setting-note">Choose a folder inside your computer’s synced OneDrive directory. The app remembers it in this browser and writes preschool-records.json after each change. OneDrive handles cloud sync. Use desktop Chrome or Edge on HTTPS or localhost. Browser security may require a click to renew access.</p><p><strong>${folder?esc(folder.name):'No folder connected'}</strong></p><div class="inline"><button id="connectFolder" class="primary">${folder?'Change folder':'Choose OneDrive folder'}</button><button id="reloadFolder" ${folder?'':'disabled'}>Reload folder data</button><button id="disconnectFolder" ${folder?'':'disabled'}>Disconnect folder</button></div><p class="setting-note">Use one editor at a time. The app checks for changed files before saving, but OneDrive sync is not a multi-user database. Keep student records out of your GitHub repository.</p></div><div class="panel"><h2>Backup & restore</h2><p class="setting-note">Excel is for reporting. A JSON backup includes photos and every year’s records and can be restored.</p><div class="inline"><button id="backup">Download JSON backup</button><label>Restore JSON backup<input type="file" id="restore" accept=".json,application/json"></label></div></div>`;
